CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260916190500_Inicial') THEN
    CREATE TABLE "MensagensOutbox" (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "MensagemId" uuid NOT NULL,
        "Tipo" character varying(100) NOT NULL,
        "Conteudo" jsonb NOT NULL,
        "OcorridoEm" timestamp with time zone NOT NULL,
        "CorrelacaoId" character varying(64),
        "PublicadaEm" timestamp with time zone,
        "Tentativas" integer NOT NULL,
        "UltimoErro" character varying(2000),
        CONSTRAINT "PK_MensagensOutbox" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260916190500_Inicial') THEN
    CREATE TABLE "Usuarios" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Nome" character varying(100) NOT NULL,
        "Email" character varying(200) NOT NULL,
        "SenhaHash" character varying(200) NOT NULL,
        "Perfil" character varying(20) NOT NULL,
        "Status" character varying(30) NOT NULL,
        "TentativasFalhas" integer NOT NULL,
        "BloqueadoAte" timestamp with time zone,
        "CriadoEm" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_Usuarios" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260916190500_Inicial') THEN
    CREATE TABLE "Eventos" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "OrganizadorId" integer NOT NULL,
        "Titulo" character varying(150) NOT NULL,
        "Descricao" character varying(4000) NOT NULL,
        "Local" character varying(150) NOT NULL,
        "Cidade" character varying(100) NOT NULL,
        "DataInicio" timestamp with time zone NOT NULL,
        "Publicado" boolean NOT NULL,
        "CriadoEm" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_Eventos" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Eventos_Usuarios_OrganizadorId" FOREIGN KEY ("OrganizadorId") REFERENCES "Usuarios" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260916190500_Inicial') THEN
    CREATE TABLE "RefreshTokens" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "UsuarioId" integer NOT NULL,
        "TokenHash" character varying(64) NOT NULL,
        "Familia" uuid NOT NULL,
        "CriadoEm" timestamp with time zone NOT NULL,
        "ExpiraEm" timestamp with time zone NOT NULL,
        "UsadoEm" timestamp with time zone,
        "RevogadoEm" timestamp with time zone,
        CONSTRAINT "PK_RefreshTokens" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_RefreshTokens_Usuarios_UsuarioId" FOREIGN KEY ("UsuarioId") REFERENCES "Usuarios" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260916190500_Inicial') THEN
    CREATE TABLE "Pedidos" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "UsuarioId" integer NOT NULL,
        "EventoId" integer NOT NULL,
        "Status" character varying(30) NOT NULL,
        "Total" numeric(10,2) NOT NULL,
        "CriadoEm" timestamp with time zone NOT NULL,
        "ExpiraEm" timestamp with time zone NOT NULL,
        "PagoEm" timestamp with time zone,
        "FinalizadoEm" timestamp with time zone,
        "CodigoPagamento" character varying(64),
        CONSTRAINT "PK_Pedidos" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Pedidos_Eventos_EventoId" FOREIGN KEY ("EventoId") REFERENCES "Eventos" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_Pedidos_Usuarios_UsuarioId" FOREIGN KEY ("UsuarioId") REFERENCES "Usuarios" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260916190500_Inicial') THEN
    CREATE TABLE "Setores" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "EventoId" integer NOT NULL,
        "Nome" character varying(80) NOT NULL,
        "Preco" numeric(10,2) NOT NULL,
        "Capacidade" integer NOT NULL,
        "Ocupados" integer NOT NULL,
        CONSTRAINT "PK_Setores" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_Setores_Ocupados" CHECK ("Ocupados" >= 0 AND "Ocupados" <= "Capacidade"),
        CONSTRAINT "FK_Setores_Eventos_EventoId" FOREIGN KEY ("EventoId") REFERENCES "Eventos" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260916190500_Inicial') THEN
    CREATE TABLE "Ingressos" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "PedidoId" integer NOT NULL,
        "SetorId" integer NOT NULL,
        "Codigo" character varying(32) NOT NULL,
        "PrecoPago" numeric(10,2) NOT NULL,
        CONSTRAINT "PK_Ingressos" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Ingressos_Pedidos_PedidoId" FOREIGN KEY ("PedidoId") REFERENCES "Pedidos" ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_Ingressos_Setores_SetorId" FOREIGN KEY ("SetorId") REFERENCES "Setores" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
