    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260916190500_Inicial') THEN
    CREATE TABLE "ItensPedido" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "PedidoId" integer NOT NULL,
        "SetorId" integer NOT NULL,
        "NomeSetor" character varying(80) NOT NULL,
        "Quantidade" integer NOT NULL,
        "PrecoUnitario" numeric(10,2) NOT NULL,
        CONSTRAINT "PK_ItensPedido" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_ItensPedido_Quantidade" CHECK ("Quantidade" > 0),
        CONSTRAINT "FK_ItensPedido_Pedidos_PedidoId" FOREIGN KEY ("PedidoId") REFERENCES "Pedidos" ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_ItensPedido_Setores_SetorId" FOREIGN KEY ("SetorId") REFERENCES "Setores" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

